def solution(cash, commands):
    shares = 0
    done = []   # 성공한 거래: (종류, 가격, 수량)
    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'UNDO':
            if done:
                kind, p, q = done.pop()
                if kind == 'BUY':
                    cash += p * q
                    shares -= q
                else:
                    cash -= p * q
                    shares += q
            continue
        p, q = int(parts[1]), int(parts[2])
        if parts[0] == 'BUY':
            if cash >= p * q:
                cash -= p * q
                shares += q
                done.append(('BUY', p, q))
        else:
            if shares >= q:
                cash += p * q
                shares -= q
                done.append(('SELL', p, q))
    return [cash, shares]
